/* Extracted from app.js; load order is intentional. */
/* ---------------- HFMS PRODUCTION CONTROL CENTER (Phase 8) ---------------- */
async function fetchFinancialControl(action, params={}){
  const q=new URLSearchParams({branch_id:state.branchId,action,...params});
  const res=await apiFetch('/api/financial-control?'+q.toString(),{headers:JSONH});
  const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||'Financial control request failed'); return data;
}
async function postFinancialControl(payload){
  const res=await apiFetch('/api/financial-control',{method:'POST',headers:JSONH,body:JSON.stringify({...payload,branch_id:state.branchId})});
  const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||'Financial control request failed'); return data;
}
async function patchFinancialControl(payload){
  const res=await apiFetch('/api/financial-control',{method:'PATCH',headers:JSONH,body:JSON.stringify({...payload,branch_id:state.branchId})});
  const data=await res.json().catch(()=>({})); if(!res.ok) throw new Error(data.error||'Financial control request failed'); return data;
}
async function loadControlCenter(){
  const data=await fetchFinancialControl('summary');
  const el=document.getElementById('hfms-control-content'); if(!el)return;
  const p=data.position||{};
  el.innerHTML=`
    <div class="grid kpi">
      <div class="card kpi"><div class="kpi-head"><h3>Revenue</h3><div class="kpi-icon tone-gold">${ic('trendUp',16)}</div></div><div class="big">${KES(p.revenue)}</div><div class="foot">Classified ledger revenue</div></div>
      <div class="card kpi"><div class="kpi-head"><h3>Expenses</h3><div class="kpi-icon tone-red">${ic('trendDown',16)}</div></div><div class="big">${KES(p.expenses)}</div><div class="foot">Including recorded charges</div></div>
      <div class="card kpi"><div class="kpi-head"><h3>Operating Result</h3><div class="kpi-icon tone-green">${ic('sparkles',16)}</div></div><div class="big">${KES(p.revenue-p.expenses)}</div><div class="foot">Revenue less expenses</div></div>
      <div class="card kpi"><div class="kpi-head"><h3>John Loan Funding</h3><div class="kpi-icon tone-gold">${ic('landmark',16)}</div></div><div class="big">${KES(p.ownerLoanFunding)}</div><div class="foot">Funding â€” not revenue</div></div>
    </div>
    <div class="form-card" style="margin-top:18px"><div class="section-head"><h2>Financial intelligence</h2><span class="tag neutral">Prediction</span></div><div id="hfms-forecast">Calculating forecastâ€¦</div></div>
    <div class="grid two-col" style="margin-top:18px">
      <div class="form-card"><div class="section-head"><h2>Cash & reconciliation</h2></div><div id="hfms-cash-list">Loading accountsâ€¦</div><div class="section-head" style="margin-top:18px"><h3>Transfer between accounts</h3></div><div class="form-row"><div><label>From</label><select id="cash-from"></select></div><div><label>To</label><select id="cash-to"></select></div></div><div class="form-row"><div><label>Amount (KES)</label><input id="cash-transfer-amount" type="number" min="0" step="0.01"></div><div><label>Reason</label><input id="cash-transfer-reason" placeholder="e.g. Move tax reserve"></div></div><button class="btn gold" id="btn-cash-transfer">Record transfer</button></div>
      <div class="form-card"><div class="section-head"><h2>Financial alerts</h2><button class="btn ghost sm" id="btn-generate-alerts">Run checks</button></div><div id="hfms-alert-list">${(data.alerts||[]).length?data.alerts.map(a=>`<div class="narrative" style="margin-bottom:8px"><b>${a.title}</b><br>${a.message}</div>`).join(''):'<div class="hint">No open alerts.</div>'}</div></div>
    </div>`;
  document.getElementById('btn-generate-alerts')?.addEventListener('click',async()=>{try{await postFinancialControl({action:'generate_alerts',period:currentOpenMonth()});await loadControlCenter()}catch(e){alert(e.message)}});
  const fiRes=await apiFetch('/api/financial-intelligence?'+new URLSearchParams({branch_id:state.branchId,months:6}),{headers:JSONH}); const fi=await fiRes.json().catch(()=>({})); const f=document.getElementById('hfms-forecast'); if(f&&fi.forecast) f.innerHTML=`<div class="grid kpi"><div class="card kpi"><h3>Next-month revenue</h3><div class="big">${KES(fi.forecast.next_month_revenue_kes)}</div></div><div class="card kpi"><h3>Next-month expenses</h3><div class="big">${KES(fi.forecast.next_month_expenses_kes)}</div></div><div class="card kpi"><h3>Projected result</h3><div class="big">${KES(fi.forecast.next_month_operating_result_kes)}</div></div></div><div class="hint">Method: ${fi.forecast.method}. This is a prediction, not a booked financial fact.</div>${(fi.alerts||[]).map(a=>`<div class="narrative" style="margin-top:8px"><b>${a.severity.toUpperCase()}</b> â€” ${a.message}</div>`).join('')}`;
  const cash=await fetchFinancialControl('cash');
  const cl=document.getElementById('hfms-cash-list'); if(cl) cl.innerHTML=(cash.accounts||[]).length?cash.accounts.map(a=>`<div class="table-row" style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line)"><span>${a.name}<small style="display:block;opacity:.65">${a.kind}</small></span><b>${KES(a.system_balance_kes)}</b></div>`).join(''):'<div class="hint">No active financial accounts.</div>';
  const opts=(cash.accounts||[]).map(a=>`<option value="${a.id}">${a.name}</option>`).join(''); document.getElementById('cash-from')?.insertAdjacentHTML('beforeend',opts); document.getElementById('cash-to')?.insertAdjacentHTML('beforeend',opts);
  document.getElementById('btn-cash-transfer')?.addEventListener('click',async()=>{const amount=Number(document.getElementById('cash-transfer-amount')?.value||0);if(amount<=0)return alert('Enter a valid amount.');try{await postFinancialControl({action:'transfer',movement_date:new Date().toISOString().slice(0,10),amount_kes:amount,from_account_id:document.getElementById('cash-from').value,to_account_id:document.getElementById('cash-to').value,reason:document.getElementById('cash-transfer-reason').value});alert('Transfer recorded.');await loadControlCenter()}catch(e){alert(e.message)}});
}
function viewControlCenter(){return `<div class="topbar"><div><h1>Financial Control Center</h1><div class="sub">Production financial position, cash controls, reconciliation and automated checks.</div></div></div><div id="hfms-control-content"><div class="form-card">Loading financial control centerâ€¦</div></div>`;}

async function loadManagementReport(){
  const from=document.getElementById('report-from')?.value; const to=document.getElementById('report-to')?.value;
  const q=new URLSearchParams({branch_id:state.branchId,from,to}); const res=await apiFetch('/api/management-report?'+q.toString(),{headers:JSONH}); const d=await res.json(); if(!res.ok)throw new Error(d.error||'Report failed');
  const s=d.summary||{}; const el=document.getElementById('management-report-output'); if(!el)return;
  el.innerHTML=`<div class="report-sheet" id="printable-financial-report"><div class="section-head"><h2>Happynet Financial Management Report</h2><span class="tag neutral">${d.period.from} â†’ ${d.period.to}</span></div><div class="grid kpi"><div class="card kpi"><h3>Revenue</h3><div class="big">${KES(s.revenue)}</div></div><div class="card kpi"><h3>Expenses</h3><div class="big">${KES(s.expenses)}</div></div><div class="card kpi"><h3>Net Profit</h3><div class="big">${KES(s.netProfit)}</div></div><div class="card kpi"><h3>Net Cash Movement</h3><div class="big">${KES(s.netCashMovement)}</div></div></div><div class="form-card" style="margin-top:16px"><h3>Owner funding</h3><p>John loan funding: <b>${KES(s.ownerLoanFunding)}</b> Â· Repayments: <b>${KES(s.ownerLoanRepayment)}</b></p></div><div class="form-card" style="margin-top:16px"><h3>Monthly trend</h3><table><thead><tr><th>Month</th><th>Revenue</th><th>Expenses</th><th>Result</th></tr></thead><tbody>${Object.entries(d.monthly||{}).map(([m,v])=>`<tr><td>${m}</td><td>${KES(v.revenue)}</td><td>${KES(v.expenses)}</td><td>${KES(v.revenue-v.expenses)}</td></tr>`).join('')}</tbody></table></div><div class="form-card" style="margin-top:16px"><h3>John / owner loan balances</h3><table><thead><tr><th>Lender</th><th>Original</th><th>Balance</th><th>Status</th></tr></thead><tbody>${(d.loans||[]).map(l=>`<tr><td>${l.lender||l.debt_name}</td><td>${KES(l.original_principal_kes)}</td><td>${KES(l.current_balance_kes)}</td><td>${l.status}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function viewReports(){const now=new Date();const first=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10);const last=now.toISOString().slice(0,10);return `<div class="topbar"><div><h1>Management Reports</h1><div class="sub">Reliable reports generated from the unified financial ledger.</div></div><div class="topbar-actions"><button class="btn ghost sm" id="btn-print-management">${ic('printer',14)}Print / PDF</button></div></div><div class="form-card"><div class="form-row"><div><label>From</label><input id="report-from" type="date" value="${first}"></div><div><label>To</label><input id="report-to" type="date" value="${last}"></div></div><button class="btn gold" id="btn-run-management-report">Generate report</button></div><div id="management-report-output" style="margin-top:18px"></div>`;}

async function loadAllocationsPro(){
 const period=currentOpenMonth()+'-01'; const res=await apiFetch('/api/allocations?branch_id='+encodeURIComponent(state.branchId)+'&period='+encodeURIComponent(period),{headers:JSONH});const d=await res.json();if(!res.ok)throw new Error(d.error||'Allocation load failed');const el=document.getElementById('allocation-pro-output');if(!el)return;
 el.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Bucket</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${(d.allocations||[]).map(a=>`<tr><td>${a.bucket}</td><td>${KES(a.amount_kes)}</td><td>${a.approved_at?'<span class="tag good">Approved</span>':'<span class="tag warn">Pending</span>'}</td><td><button class="btn ghost sm" data-alloc-approve="${a.id}">Approve</button> <button class="btn ghost sm" data-alloc-proof="${a.id}">Record proof</button></td></tr>`).join('')}</tbody></table></div>`;
 el.querySelectorAll('[data-alloc-approve]').forEach(b=>b.addEventListener('click',async()=>{try{await apiFetch('/api/allocations',{method:'PATCH',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,id:b.dataset.allocApprove,action:'approve',reason:'Approved through HFMS control workflow'})});await loadAllocationsPro()}catch(e){alert(e.message)}}));
 el.querySelectorAll('[data-alloc-proof]').forEach(b=>b.addEventListener('click',async()=>{const actual=prompt('Actual transferred amount (KES):');if(actual===null)return;const ref=prompt('Proof/reference (transaction ID, bank ref, etc.):')||'';try{await apiFetch('/api/allocations',{method:'PATCH',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,id:b.dataset.allocProof,action:'proof',actual_amount_kes:Number(actual),proof_reference:ref,reason:'Allocation transfer proof recorded'})});alert('Proof recorded for verification.');await loadAllocationsPro()}catch(e){alert(e.message)}}));
}
function viewAllocationsPro(){return `<div class="topbar"><div><h1>Profit First Control</h1><div class="sub">Allocation approval, actual transfer proof and auditability.</div></div></div><div class="narrative"><b>Control rule:</b> calculated allocations are not treated as completed transfers until they are approved and supported by a proof/reference.</div><div id="allocation-pro-output" class="form-card" style="margin-top:18px">Loading allocationsâ€¦</div>`;}


async function loadProductionControls(){
  const el=document.getElementById('production-controls-output'); if(!el)return;
  try{
    const q=new URLSearchParams({branch_id:state.branchId});
    const [bud,rec,anom]=await Promise.all([
      apiFetch('/api/budgets?'+q,{headers:JSONH}).then(r=>r.json()),
      apiFetch('/api/recurring-expenses?'+q,{headers:JSONH}).then(r=>r.json()),
      apiFetch('/api/anomalies?'+q,{headers:JSONH}).then(r=>r.json())
    ]);
    el.innerHTML=`<div class="grid kpi">
      <div class="card kpi"><h3>Budget lines</h3><div class="big">${(bud.budgets||[]).length}</div></div>
      <div class="card kpi"><h3>Recurring expenses</h3><div class="big">${(rec.items||[]).filter(x=>x.active).length}</div></div>
      <div class="card kpi"><h3>Open anomalies</h3><div class="big">${(anom.events||[]).filter(x=>x.status==='open').length}</div></div>
    </div>
    <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Budget vs Actual</h3></div>
      ${(bud.budgets||[]).length?`<table><thead><tr><th>Period</th><th>Budget</th><th>Actual</th><th>Variance</th></tr></thead><tbody>${(bud.budgets||[]).map(x=>`<tr><td>${x.period}</td><td>${KES(x.budget_kes)}</td><td>${KES(x.actual_kes)}</td><td class="${Number(x.variance_kes)>0?'bad':'good'}">${KES(x.variance_kes)}</td></tr>`).join('')}</tbody></table>`:'<div class="hint">No budget lines configured yet.</div>'}
    </div>
    <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Recurring expenses</h3></div>
      ${(rec.items||[]).length?`<table><thead><tr><th>Description</th><th>Amount</th><th>Frequency</th><th>Next Due</th><th>Status</th></tr></thead><tbody>${(rec.items||[]).map(x=>`<tr><td>${x.description}</td><td>${KES(x.amount_kes)}</td><td>${x.frequency}</td><td>${x.next_due_date}</td><td>${x.active?'Active':'Paused'}</td></tr>`).join('')}</tbody></table>`:'<div class="hint">No recurring expenses configured.</div>'}
    </div>
    <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Anomaly detection</h3><button class="btn ghost sm" id="btn-scan-anomalies">Run scan</button></div>
      <div id="anomaly-list">${(anom.events||[]).filter(x=>x.status==='open').slice(0,20).map(x=>`<div class="narrative" style="margin-top:8px"><b>${x.severity.toUpperCase()}</b> â€” ${x.message}</div>`).join('')||'<div class="hint">No open anomalies.</div>'}</div>
    </div>`;
    document.getElementById('btn-scan-anomalies')?.addEventListener('click',async()=>{try{await apiFetch('/api/anomalies',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,action:'scan'})});await loadProductionControls();}catch(e){alert(e.message)}});
    document.getElementById('btn-executive-snapshot')?.addEventListener('click',async()=>{
      const out=document.getElementById('executive-snapshot-output'); out.innerHTML='<div class="hint">Calculating live financial healthâ€¦</div>';
      try{
        const rr=await apiFetch('/api/executive-command-center?branch_id='+encodeURIComponent(state.branchId)); if(!rr.ok) throw new Error((await rr.text())||'Unable to load snapshot.'); const x=await rr.json();
        const k=x.kpis||{}, fmt=v=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(Number(v||0));
        out.innerHTML=`<div class="grid-3"><div class="stat"><div class="stat-label">Revenue</div><div class="stat-value num">${fmt(k.revenue)}</div></div><div class="stat"><div class="stat-label">Operating Result</div><div class="stat-value num">${fmt(k.operating_result)}</div></div><div class="stat"><div class="stat-label">Cash Runway</div><div class="stat-value">${k.cash_runway_months==null?'Not determinable':k.cash_runway_months.toFixed(1)+' months'}</div></div></div><div class="narrative" style="margin-top:12px"><b>Management health</b><br>${(x.health||[]).map(h=>`<div style="margin-top:6px"><b>${h.severity.toUpperCase()}</b> â€” ${h.message}</div>`).join('')||'No immediate control flags from the current ledger snapshot.'}</div>`;
      }catch(e){out.innerHTML='<div class="err-msg">'+e.message+'</div>';}
    });
    document.getElementById('btn-run-scenario')?.addEventListener('click',async()=>{
      const out=document.getElementById('scenario-output'); out.textContent='Running non-posting scenarioâ€¦';
      try{
        const rr=await apiFetch('/api/financial-scenario',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,revenue_change_pct:Number(document.getElementById('scenario-revenue').value||0),expense_change_pct:Number(document.getElementById('scenario-expense').value||0),months:Number(document.getElementById('scenario-months').value||6)})}); if(!rr.ok) throw new Error((await rr.text())||'Scenario failed.'); const x=await rr.json();
        const r=x.result||{}, fmt=v=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(Number(v||0));
        out.innerHTML=`<b>FORECAST â€” scenario only</b><br>Monthly revenue: ${fmt(r.monthly_revenue)}<br>Monthly expenses: ${fmt(r.monthly_expenses)}<br>Monthly operating result: ${fmt(r.monthly_operating_result)}<br>Period result: ${fmt(r.period_operating_result)}<div class="hint" style="margin-top:8px">${x.note||''}</div>`;
      }catch(e){out.innerHTML='<div class="err-msg">'+e.message+'</div>';}
    });

  }catch(e){el.innerHTML='<div class="err-msg">'+e.message+'</div>';}
}
function viewAutomationCenter(){
  return `<div class="topbar"><div><h1>Automation Command Center</h1><div class="sub">Proactive financial controls, scheduled alerts, recurring workflows and notification delivery.</div></div><div><button class="btn gold" id="btn-run-automation">Run automation now</button></div></div>
  <div class="grid-3">
    <div class="stat"><div class="stat-label">Automation</div><div class="stat-value">24/7 control layer</div><div class="hint">Rules evaluate financial conditions without changing actual books unless explicitly authorized.</div></div>
    <div class="stat"><div class="stat-label">Notifications</div><div class="stat-value" id="automation-queue-count">Loadingâ€¦</div><div class="hint">In-app, email, SMS or webhook delivery.</div></div>
    <div class="stat"><div class="stat-label">Safety</div><div class="stat-value">Approval-aware</div><div class="hint">Financial auto-execution is disabled by default.</div></div>
  </div>
  <div class="form-card"><div class="section-head"><h3>Automation rules</h3><span class="tag neutral">Branch scoped</span></div><div id="automation-rules"><div class="hint">Loading rulesâ€¦</div></div></div>
  <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Recent automation events</h3><span class="tag neutral">Audit trail</span></div><div id="automation-events"><div class="hint">Loading eventsâ€¦</div></div></div>
  <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Notification queue</h3><span class="tag neutral">Delivery status</span></div><div id="automation-queue"><div class="hint">Loading queueâ€¦</div></div></div>
  <div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Automation runs</h3></div><div id="automation-runs"><div class="hint">Loading runsâ€¦</div></div></div>`;
}
async function loadAutomationCenter(){
  const rulesEl=document.getElementById('automation-rules'); if(!rulesEl)return;
  try{
    const r=await apiFetch('/api/automation-center?'+new URLSearchParams({branch_id:state.branchId}),{headers:JSONH});
    const d=await r.json(); if(!r.ok)throw new Error(d.error||'Automation center unavailable.');
    const rules=d.rules||[];
    rulesEl.innerHTML=rules.length?`<table><thead><tr><th>Rule</th><th>Severity</th><th>Channel</th><th>Enabled</th><th>Auto execute</th><th>Lead days</th><th>Action</th></tr></thead><tbody>${rules.map(x=>`<tr>
      <td><b>${execEsc(x.name)}</b><div class="hint">${execEsc(x.description||'')}</div></td>
      <td><span class="tag ${x.severity==='critical'?'bad':x.severity==='warning'?'warn':'neutral'}">${x.severity}</span></td>
      <td><select data-auto-channel="${x.rule_key}"><option value="in_app" ${x.channel==='in_app'?'selected':''}>In-app</option><option value="email" ${x.channel==='email'?'selected':''}>Email</option><option value="sms" ${x.channel==='sms'?'selected':''}>SMS</option><option value="webhook" ${x.channel==='webhook'?'selected':''}>Webhook</option></select></td>
      <td><input type="checkbox" data-auto-enabled="${x.rule_key}" ${x.enabled?'checked':''}></td>
      <td><input type="checkbox" data-auto-execute="${x.rule_key}" ${x.auto_execute?'checked':''} ${!['recurring_due'].includes(x.rule_key)?'title="Only supported controlled actions can execute automatically"':''}></td>
      <td><input style="width:70px" type="number" min="0" data-auto-lead="${x.rule_key}" value="${Number(x.lead_days||0)}"></td>
      <td><button class="btn ghost sm" data-save-auto="${x.rule_key}">Save</button></td>
    </tr>`).join('')}</tbody></table>`:'<div class="hint">No automation rules configured.</div>';
    document.getElementById('automation-queue-count').textContent=`${(d.queue||[]).filter(x=>['queued','failed'].includes(x.status)).length} pending`;
    const events=d.events||[];
    document.getElementById('automation-events').innerHTML=events.length?`<table><thead><tr><th>Time</th><th>Rule</th><th>Severity</th><th>Event</th></tr></thead><tbody>${events.slice(0,20).map(x=>`<tr><td>${x.created_at?.slice(0,19).replace('T',' ')||''}</td><td>${execEsc(x.rule_key)}</td><td>${x.severity}</td><td>${execEsc(x.message)}</td></tr>`).join('')}</tbody></table>`:'<div class="hint">No automation events.</div>';
    const q=d.queue||[];
    document.getElementById('automation-queue').innerHTML=q.length?`<table><thead><tr><th>Created</th><th>Rule</th><th>Channel</th><th>Status</th><th>Error</th></tr></thead><tbody>${q.slice(0,20).map(x=>`<tr><td>${x.created_at?.slice(0,19).replace('T',' ')||''}</td><td>${execEsc(x.rule_key)}</td><td>${x.channel}</td><td>${x.status}</td><td>${execEsc(x.last_error||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="hint">Notification queue is empty.</div>';
    const runs=d.runs||[];
    document.getElementById('automation-runs').innerHTML=runs.length?`<table><thead><tr><th>Started</th><th>Trigger</th><th>Status</th><th>Notifications</th><th>Actions</th></tr></thead><tbody>${runs.map(x=>`<tr><td>${x.started_at?.slice(0,19).replace('T',' ')||''}</td><td>${x.trigger}</td><td>${x.status}</td><td>${x.notifications_sent||0}/${x.notifications_created||0}</td><td>${x.actions_executed||0}/${x.actions_prepared||0}</td></tr>`).join('')}</tbody></table>`:'<div class="hint">No automation runs yet.</div>';
    document.querySelectorAll('[data-save-auto]').forEach(btn=>btn.addEventListener('click',async()=>{
      const key=btn.dataset.saveAuto;
      const payload={action:'update_rule',branch_id:state.branchId,rule_key:key,enabled:document.querySelector(`[data-auto-enabled="${key}"]`).checked,channel:document.querySelector(`[data-auto-channel="${key}"]`).value,lead_days:Number(document.querySelector(`[data-auto-lead="${key}"]`).value||0),auto_execute:document.querySelector(`[data-auto-execute="${key}"]`).checked};
      try{const rr=await apiFetch('/api/automation-center',{method:'POST',headers:JSONH,body:JSON.stringify(payload)});const x=await rr.json();if(!rr.ok)throw new Error(x.error||'Could not save rule');await loadAutomationCenter();}catch(e){alert(e.message);}
    }));
    document.getElementById('btn-run-automation')?.addEventListener('click',async()=>{
      const out=document.getElementById('automation-events');out.innerHTML='<div class="hint">Running automationâ€¦</div>';
      try{const rr=await apiFetch('/api/automation-runner',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId})});const x=await rr.json();if(!rr.ok)throw new Error(x.error||'Automation failed');await loadAutomationCenter();alert(`Automation completed. ${x.created||0} notifications created, ${x.delivery?.sent||0} delivered.`);}catch(e){alert(e.message);await loadAutomationCenter();}
    });
  }catch(e){rulesEl.innerHTML=`<div class="err-msg">${execEsc(e.message)}</div>`;}
}
