function execMoney(v){ return KES(Number(v||0)); }
function execEsc(v){ return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
async function loadExecutiveManagement(){
  const out=document.getElementById('executive-management-output'); if(!out)return;
  out.innerHTML='<div class="hint">Building the executive position from the live financial ledgerâ€¦</div>';
  try{
    const r=await apiFetch('/api/executive-management?'+new URLSearchParams({branch_id:state.branchId}),{headers:JSONH});
    const d=await r.json(); if(!r.ok)throw new Error(d.error||'Executive management unavailable.');
    const m=d.metrics||{};
    const sev={critical:'alert',high:'alert',medium:'warn',good:'good'};
    const health=(d.priorities||[]).slice(0,8).map(x=>`<div class="item"><span class="tag ${sev[x.severity]||'neutral'}">${execEsc(x.severity||'info')}</span><span class="txt">${execEsc(x.message)}</span></div>`).join('')||'<div class="hint">No active management risks detected.</div>';
    const monthly=(m.monthly||[]).slice(-6).map(x=>`<tr><td>${execEsc(x.month)}</td><td class="num">${execMoney(x.revenue)}</td><td class="num">${execMoney(x.expenses)}</td><td class="num">${execMoney((x.revenue||0)-(x.expenses||0))}</td><td class="num">${execMoney(x.net_cash)}</td></tr>`).join('');
    const decisions=(d.decisions||[]).slice(0,8).map(x=>`<div class="decision-row"><div><b>${execEsc(x.title)}</b><div class="hint">${execEsc(x.recommended_action||x.description||'No action note')}</div></div><div style="display:flex;gap:6px;align-items:center"><span class="tag ${x.priority==='critical'||x.priority==='high'?'alert':x.priority==='medium'?'warn':'neutral'}">${execEsc(x.priority)}</span><select class="exec-decision-status" data-id="${x.id}"><option ${x.status==='open'?'selected':''}>open</option><option ${x.status==='in_progress'?'selected':''}>in_progress</option><option ${x.status==='completed'?'selected':''}>completed</option><option ${x.status==='dismissed'?'selected':''}>dismissed</option></select></div></div>`).join('')||'<div class="hint">No open management decisions.</div>';
    out.innerHTML=`
      <div class="grid kpi">
        <div class="card kpi"><div class="kpi-head"><h3>Revenue</h3><div class="kpi-icon tone-gold">${ic('trendUp',16)}</div></div><div class="big">${execMoney(m.revenue)}</div><div class="foot">Growth: ${m.recent_revenue_growth_pct==null?'n/a':Number(m.recent_revenue_growth_pct).toFixed(1)+'%'}</div></div>
        <div class="card kpi"><div class="kpi-head"><h3>Expenses</h3><div class="kpi-icon tone-navy">${ic('receipt',16)}</div></div><div class="big">${execMoney(m.expenses)}</div><div class="foot">Recent avg: ${execMoney(m.recent_avg_expenses)}</div></div>
        <div class="card kpi"><div class="kpi-head"><h3>Operating Result</h3><div class="kpi-icon tone-good">${ic('target',16)}</div></div><div class="big">${execMoney(m.operating_result)}</div><div class="foot">Ledger-based result</div></div>
        <div class="card kpi"><div class="kpi-head"><h3>Available Cash</h3><div class="kpi-icon tone-navy">${ic('wallet',16)}</div></div><div class="big">${execMoney(m.cash_balance)}</div><div class="foot">Runway: ${m.cash_runway_months==null?'n/a':Number(m.cash_runway_months).toFixed(1)+' months'}</div></div>
        <div class="card kpi"><div class="kpi-head"><h3>John / Owner Loan</h3><div class="kpi-icon tone-gold">${ic('handshake',16)}</div></div><div class="big">${execMoney(m.owner_loan_balance)}</div><div class="foot">Funding ${execMoney(m.owner_funding)} Â· Repayment ${execMoney(m.owner_repayments)}</div></div>
        <div class="card kpi"><div class="kpi-head"><h3>Profit First Open</h3><div class="kpi-icon tone-navy">${ic('piggyBank',16)}</div></div><div class="big">${m.open_profit_first_allocations||0}</div><div class="foot">Open allocation amount: ${execMoney(m.open_profit_first_amount)}</div></div>
      </div>
      <div class="grid-2" style="margin-top:18px">
        <div class="form-card"><div class="section-head"><h2>Management attention</h2><span class="hint">Prioritized from live data</span></div><div class="list">${health}</div></div>
        <div class="form-card"><div class="section-head"><h2>Executive decision queue</h2><button class="btn ghost sm" id="btn-exec-new-decision">New decision</button></div><div id="exec-decisions">${decisions}</div></div>
      </div>
      <div class="form-card" style="margin-top:18px"><div class="section-head"><h2>Six-month management trend</h2><button class="btn gold sm" id="btn-exec-print">Print executive pack</button></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>Revenue</th><th>Expenses</th><th>Operating result</th><th>Net cash</th></tr></thead><tbody>${monthly||'<tr><td colspan="5">No classified ledger data.</td></tr>'}</tbody></table></div></div>
      <div class="form-card" style="margin-top:18px"><div class="section-head"><h2>KPI targets</h2><span class="hint">Targets guide management; they never alter accounting records.</span></div><div class="form-row"><div><label>Metric</label><select id="exec-target-metric"><option value="revenue">Monthly revenue</option><option value="operating_result">Operating result</option><option value="cash_balance">Minimum cash</option><option value="profit_first_compliance">Profit First compliance %</option></select></div><div><label>Target</label><input id="exec-target-value" type="number" step="0.01"></div><div><label>Start</label><input id="exec-target-start" type="date" value="${new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)}"></div><div><label>End</label><input id="exec-target-end" type="date" value="${new Date().toISOString().slice(0,10)}"></div></div><button class="btn gold" id="btn-exec-save-target">Save target</button><div id="exec-target-status" class="hint" style="margin-top:8px"></div></div>
      <div class="form-card" style="margin-top:18px"><div class="section-head"><h2>AI management brief</h2><button class="btn gold" id="btn-exec-ai-brief">Generate CFO briefing</button></div><div class="hint">The briefing is generated from the live executive context. Facts, forecasts and recommendations remain explicitly separated.</div><div id="exec-ai-brief" class="narrative" style="margin-top:12px"></div></div>`;
    document.querySelectorAll('.exec-decision-status').forEach(sel=>sel.addEventListener('change',async()=>{try{const rr=await apiFetch('/api/executive-management',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,action:'update_decision',id:sel.dataset.id,status:sel.value})});if(!rr.ok){const z=await rr.json();throw new Error(z.error||'Update failed')}await loadExecutiveManagement();}catch(e){alert(e.message)}}));
    document.getElementById('btn-exec-new-decision')?.addEventListener('click',async()=>{const title=prompt('Decision title');if(!title)return;const recommended_action=prompt('Recommended action (optional)')||null;try{const rr=await apiFetch('/api/executive-management',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,action:'create_decision',title,recommended_action,priority:'medium',source:'executive'})});const z=await rr.json();if(!rr.ok)throw new Error(z.error||'Could not create decision');await loadExecutiveManagement();}catch(e){alert(e.message)}});
    document.getElementById('btn-exec-save-target')?.addEventListener('click',async()=>{try{const rr=await apiFetch('/api/executive-management',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,action:'set_target',metric_key:document.getElementById('exec-target-metric').value,target_value:Number(document.getElementById('exec-target-value').value),period_start:document.getElementById('exec-target-start').value,period_end:document.getElementById('exec-target-end').value})});const z=await rr.json();if(!rr.ok)throw new Error(z.error||'Target failed');document.getElementById('exec-target-status').textContent='Target saved.';await loadExecutiveManagement();}catch(e){alert(e.message)}});
    document.getElementById('btn-exec-ai-brief')?.addEventListener('click',async()=>{const o=document.getElementById('exec-ai-brief');o.textContent='HFMS CFO is preparing the management briefingâ€¦';try{const rr=await apiFetch('/api/ai-cfo',{method:'POST',headers:JSONH,body:JSON.stringify({branch_id:state.branchId,question:'Prepare an executive management briefing. Separate FACTS, CALCULATIONS, FORECASTS, RISKS and RECOMMENDATIONS. Prioritize decisions management should make today. Do not invent any financial figures.',history:[]})});const z=await rr.json();if(!rr.ok)throw new Error(z.error||'AI briefing failed');o.innerHTML='<b>HFMS CFO</b><div style="white-space:pre-wrap;margin-top:8px">'+execEsc(z.answer||'No briefing returned.')+'</div>'; }catch(e){o.textContent=e.message}});
    document.getElementById('btn-exec-print')?.addEventListener('click',()=>window.print());
  }catch(e){out.innerHTML='<div class="err-msg">'+execEsc(e.message)+'</div>';}
}

function viewExecutiveManagement(){
  return `<div class="topbar"><div><h1>Executive Command Center</h1><div class="sub">A decision-focused management layer for Happynet â€” actuals from the ledger, Profit First discipline, cash intelligence and controlled management actions.</div></div><div class="topbar-actions"><span class="tag good">LIVE LEDGER</span><button class="btn ghost sm" id="btn-exec-refresh">Refresh</button></div></div><div class="narrative"><b>Management rule:</b> accounting records remain the source of truth. Profit First governs cash discipline. Forecasts never rewrite actuals. AI recommendations require controlled approval before financial actions.</div><div id="executive-management-output" style="margin-top:18px"></div>`;
}

function viewSecurityCenter(){return `<div class="topbar"><div><div class="eyebrow">Enterprise security</div><h1>Security Command Center</h1><div class="sub">A protected control plane for identity, branch isolation, approvals, auditability, period locks, AI guardrails and notification safety.</div></div><div class="topbar-actions"><span class="tag good">HEAD OFFICE</span><button class="btn gold sm" id="btn-security-smoke">Run control test</button></div></div><div id="security-center-output"><div class="hint">Loading security controlsâ€¦</div></div>`;}
async function loadSecurityCenter(){const out=document.getElementById('security-center-output');if(!out)return;try{const r=await apiFetch('/api/security-center',{headers:JSONH});const d=await r.json();if(!r.ok)throw new Error(d.error||'Security center unavailable');const score=Number(d.score||0);const scoreClass=score>=90?'good':score>=70?'warn':'bad';out.innerHTML=`<div class="security-grid"><div class="stat"><div class="stat-label">Control score</div><div class="security-score">${score}%</div><div class="hint">${score>=90?'Strong control posture':score>=70?'Review recommended':'Immediate review required'}</div></div><div class="stat"><div class="stat-label">Access grants</div><div class="big">${(d.grants||[]).length}</div><div class="hint">Branch and Head Office permissions</div></div><div class="stat"><div class="stat-label">Roles</div><div class="big">${new Set((d.grants||[]).map(x=>x.role)).size}</div><div class="hint">RBAC roles represented</div></div><div class="stat"><div class="stat-label">Security events</div><div class="big">${(d.events||[]).length}</div><div class="hint">Recent evidence retained</div></div></div><div class="grid-2" style="margin-top:16px"><div class="form-card"><div class="section-head"><h3>Control framework</h3><span class="tag ${scoreClass}">${score>=90?'Healthy':score>=70?'Review':'Action required'}</span></div>${(d.controls||[]).map(c=>`<div class="security-control"><div><b>${execEsc(c.name)}</b><div class="hint">${execEsc(c.description||'')}</div></div><span class="tag ${c.status==='PASS'?'good':'neutral'}">${execEsc(c.status)}</span></div>`).join('')}</div><div class="form-card"><div class="section-head"><h3>Role coverage</h3><span class="tag neutral">RBAC</span></div>${(d.role_coverage||[]).map(r=>`<div class="security-control"><div><b>${execEsc(r.role.replace(/_/g,' '))}</b><div class="hint">Read ${r.read?'yes':'no'} Â· Write ${r.write?'yes':'no'} Â· Approval ${r.approval?'yes':'no'}</div></div><span class="tag ${r.approval?'gold':'neutral'}">${r.approval?'Approver':'Operator'}</span></div>`).join('')}</div></div><div class="form-card" style="margin-top:16px"><div class="section-head"><h3>Recent security evidence</h3><span class="tag neutral">Append-only</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>Time</th><th>Event</th><th>Action</th><th>Resource</th><th>Result</th></tr></thead><tbody>${(d.events||[]).map(e=>`<tr><td>${new Date(e.created_at).toLocaleString()}</td><td>${execEsc(e.event_type)}</td><td>${execEsc(e.action)}</td><td>${execEsc(e.resource||'â€”')}</td><td><span class="tag ${e.result==='PASS'||e.result==='SUCCESS'?'good':'neutral'}">${execEsc(e.result)}</span></td></tr>`).join('')||'<tr><td colspan=5 class="hint">No recent security events.</td></tr>'}</tbody></table></div></div><div class="narrative" style="margin-top:16px"><b>Security principle:</b> the accounting ledger remains the source of truth; AI and automation can recommend or prepare actions, while authentication, branch RBAC, approvals, period controls and audit evidence govern execution.</div>`;document.getElementById('btn-security-smoke')?.addEventListener('click',async()=>{const b=document.getElementById('btn-security-smoke');b.disabled=true;b.textContent='Testingâ€¦';try{const rr=await apiFetch('/api/security-center',{method:'POST',headers:JSONH,body:JSON.stringify({action:'run_smoke_test'})});const x=await rr.json();if(!rr.ok)throw new Error(x.error||'Security test failed');alert(`Security control test: ${x.score}%`);await loadSecurityCenter();}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent='Run control test';}});}catch(e){out.innerHTML=`<div class="err-msg">${execEsc(e.message)}</div>`;}}


function viewSystemHealth(){return `<div class="topbar"><div><div class="eyebrow">Production engineering</div><h1>System Health</h1><div class="sub">Live verification of the deployed HFMS code, Supabase data plane, authentication environment and critical financial services.</div></div><div class="topbar-actions"><span class="tag neutral">HEAD OFFICE</span><button class="btn gold sm" id="btn-system-health-refresh">Run live check</button></div></div><div id="system-health-output"><div class="hint">Checking the production environmentâ€¦</div></div>`;}
async function loadSystemHealth(){
  const out=document.getElementById('system-health-output'); if(!out)return;
  try{
    const r=await apiFetch('/api/system-health',{headers:JSONH}); const d=await r.json();
    if(!r.ok) throw new Error(d.error||'System health unavailable.');
    const score=Number(d.score||0), tone=score>=95?'good':score>=80?'warn':'alert';
    const rows=(d.checks||[]).map(c=>`<tr><td>${execEsc(c.table||c.function||c.key)}</td><td><span class="tag ${c.status==='PASS'?'good':c.status==='FAIL'?'alert':'warn'}">${execEsc(c.status)}</span></td><td>${execEsc(c.detail|| (c.configured?'configured':'not configured'))}</td></tr>`).join('');
    out.innerHTML=`<div class="grid kpi"><div class="card kpi"><div class="kpi-head"><h3>Integration score</h3><div class="kpi-icon tone-gold">${ic('activity',16)}</div></div><div class="big">${score}%</div><div class="foot">${score>=95?'Production checks healthy':score>=80?'Review failed checks':'Production integration needs attention'}</div></div><div class="card kpi"><h3>Supabase tables</h3><div class="big">${(d.tables||[]).filter(x=>x.status==='PASS').length}/${(d.tables||[]).length}</div><div class="foot">Critical data-plane checks</div></div><div class="card kpi"><h3>Functions</h3><div class="big">${(d.functions||[]).filter(x=>x.status==='PASS').length}/${(d.functions||[]).length}</div><div class="foot">Critical API functions present</div></div><div class="card kpi"><h3>Environment</h3><div class="big">${(d.environment||[]).filter(x=>x.configured).length}/${(d.environment||[]).length}</div><div class="foot">Server-side secrets configured</div></div></div><div class="form-card" style="margin-top:18px"><div class="section-head"><h2>Live integration checks</h2><span class="tag ${tone}">${score}%</span></div><div class="table-wrap"><table><thead><tr><th>Check</th><th>Status</th><th>Detail</th></tr></thead><tbody>${rows}</tbody></table></div></div><div class="narrative" style="margin-top:16px"><b>Engineering rule:</b> code presence is not treated as feature completion. HFMS only treats a service as production-ready when its implementation, database dependency, authentication path and live integration can be verified.</div>`;
    document.getElementById('btn-system-health-refresh')?.addEventListener('click',loadSystemHealth);
  }catch(e){out.innerHTML=`<div class="err-msg">${execEsc(e.message)}</div>`;}
}

function visibleTabs(){ return TABS.filter(t => !t.headOfficeOnly || (state && state.isHeadOffice)); }
let activeTab = 'dashboard';
let flashError = '';
let confirmCloseMonth = false;

function setTab(id){
  activeTab = id; flashError=''; render(); window.scrollTo(0,0);
  if(id==='staff' && state.isHeadOffice && !staffState.branches) loadStaffData();
}

function root(){ return document.getElementById('root'); }

function render(){
  const r = root();
  let d = null;
  try{ d = dashboardData(); }catch(e){ d = null; }
  const tabs = visibleTabs();
  r.innerHTML = `
    <div class="app">
      <div class="sidebar no-print">
        <div class="brand">
          <div class="brand-mark">${ic('sparkles',18)}</div>
          <div class="brand-text">happy<span class="accent">net</span><span class="sublabel">Profit First</span></div>
        </div>

        ${state.allBranches && state.allBranches.length > 1 ? `
        <div class="branch-switch">
          <select id="branch-select">
            ${state.allBranches.map(b=>`<option value="${b.branch_id}" ${b.branch_id===state.branchId?'selected':''}>${b.name}</option>`).join('')}
          </select>
        </div>` : ''}

        <nav>
          ${TAB_GROUPS.map(group => {
            const visibleGroupTabs = group.tabs.filter(t => !t.headOfficeOnly || state.isHeadOffice);
            return visibleGroupTabs.length === 0 ? '' : `
              <div class="nav-section">
                <div class="nav-section-label">${group.section}</div>
                ${visibleGroupTabs.map(t => `<button data-tab="${t.id}" class="${activeTab===t.id?'active':''}">${ic(t.icon,17)}<span>${t.label}</span></button>`).join('')}
              </div>
            `;
          }).join('')}
        </nav>

        <div class="sidebar-widget">
          <div class="sidebar-widget-head"><span>${monthLabel(currentOpenMonth())}</span><span class="tag neutral" style="font-size:10px;">Open</span></div>
          ${d ? `
          <div class="mini-progress">
            <div class="mini-progress-row"><span>Revenue pace</span><b>${d.revenuePacePct.toFixed(0)}%</b></div>
            <div class="mini-progress-track"><div class="mini-progress-fill" style="width:${Math.min(100,d.revenuePacePct)}%; background:var(--gold);"></div></div>
            <div class="mini-progress-row" style="margin-top:9px;"><span>OpEx used</span><b>${d.opexPacePct.toFixed(0)}%</b></div>
            <div class="mini-progress-track"><div class="mini-progress-fill" style="width:${Math.min(100,d.opexPacePct)}%; background:${d.overspent?'var(--alert)':'var(--good)'};"></div></div>
          </div>` : ''}
        </div>

        <div class="sidebar-foot">
          <div id="save-badge" class="save-badge"></div>
          <div class="profile-chip">
            <div class="profile-avatar">${(currentUserEmail||'?').charAt(0).toUpperCase()}</div>
            <div class="profile-info">
              <div class="profile-email">${currentUserEmail||''}</div>
              <div class="profile-role">${state && state.role ? state.role.replace(/_/g,' ') : ''}</div>
            </div>
            <button id="btn-sign-out" title="Sign out">${ic('logout',16)}</button>
          </div>
        </div>
      </div>
      <div class="main" id="main"></div>
    </div>
    <div class="mobile-tabs no-print">${tabs.map(t=>`<button data-tab="${t.id}" class="${activeTab===t.id?'active':''}">${t.label}</button>`).join('')}</div>
  `;
  r.querySelectorAll('[data-tab]').forEach(b => b.addEventListener('click', ()=>setTab(b.dataset.tab)));
  const branchSelect = document.getElementById('branch-select');
  if(branchSelect) branchSelect.addEventListener('change', ()=> switchBranch(branchSelect.value));
  const signOutBtn = document.getElementById('btn-sign-out');
  if(signOutBtn) signOutBtn.addEventListener('click', async ()=>{ await apiLogout(); location.reload(); });
  renderSaveBadge();
  renderMain();
}

